//! 🧪️ Native original Toy fields, canonical bytes and actual backing conserve receipts under independent denial and cancellation.
use super::*;
use semio_framework_job::{Generation,OperationId,JobPayloadAuthority,StepBudget};
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_toy_operation_source_preserves_canonical_native_wire_and_original_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=law["policy"].as_array().unwrap();let grant=RetainedCloneGrant{maximum_items:p[0].as_u64().unwrap()as usize,maximum_copy_bytes:p[1].as_u64().unwrap()as usize,maximum_capacity_bytes:p[2].as_u64().unwrap()as usize,maximum_release_bytes:p[3].as_u64().unwrap()as usize,maximum_depth:p[4].as_u64().unwrap()as usize};let cancel=semio_framework_job::root_cancel_token();let operation=OperationId(90127);let generation=Generation(3);
 for row in law["cases"].as_array().unwrap(){for tag in[0,1]{let count=row["count"].as_i64().unwrap()as i32;let unit=row["unit"].as_u64().unwrap()as u32;let expected:TestMutation=if tag==0{crate::test_app_mutation_fixture::SetCount{value:count}.into()}else{crate::test_app_mutation_fixture::SetLabel{value:row["label"].as_str().unwrap().into()}.into()};let canonical=protocol::OpBinary::encode_op(&expected).unwrap();for cut in[0,1,2,5,usize::MAX]{let((mut authority,birth),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_eq!((birth.retained_capacity_bytes,birth.released_bytes),heap);assert_eq!(birth.copied_bytes,0);let mut born=heap.0;let mut released=heap.1;let mut sequence=0;let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,semio_framework_job::logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(mut source,heap)=observe(||if tag==0{OriginalToyOperationSource::admit_count(count,&mut cx).unwrap().unwrap()}else{OriginalToyOperationSource::admit_label(unit,&mut cx).unwrap().unwrap()});assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress().copied_bytes,if tag==0{0}else{row["label"].as_str().unwrap().len()});drop(cx);let original=&source.fields as*const _;let mut turns=0;
 while !source.is_ready()&&turns<cut{for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let pointer=source.original_wire().map(|wire|wire.as_ptr());let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,semio_framework_job::logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(_,heap)=observe(||source.advance(&mut cx).unwrap());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());assert_eq!(source.original_wire().map(|wire|wire.as_ptr()),pointer);assert_eq!(&source.fields as*const _,original);}let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,semio_framework_job::logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(_,heap)=observe(||source.advance(&mut cx).unwrap());let progress=cx.retained_progress();assert!(progress.fits(grant));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap);born+=heap.0;released+=heap.1;turns+=1;assert!(turns<100000);}
 if source.is_ready(){assert_eq!(source.original_wire().unwrap(),canonical);assert_eq!(protocol::OpBinary::decode_op(source.original_wire().unwrap()).unwrap(),expected);}
 while !source.terminal_is_empty(){let demand=source.retirement_demands().unwrap();for denied in[Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),Some(RetainedCloneGrant{maximum_depth:0,..grant})].into_iter().flatten(){let pointer=source.original_wire().map(|wire|wire.as_ptr());let(step,heap)=observe(||source.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(source.original_wire().map(|wire|wire.as_ptr()),pointer);}let(step,heap)=observe(||source.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);born+=heap.0;released+=heap.1;}
 let(step,heap)=observe(||authority.close_step(grant).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;assert_eq!(born,released);let(_,heap)=observe(||{drop(source);drop(authority);});assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original Toy operation tag={tag} unit={unit} cancellation={cut} source={original:p} canonicalBytes={} turns={turns} physical={released} metadataCopy0 terminalDrop0",canonical.len());}}}
}
